	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		BankSortAssistService.BankSortAssistItem current = plugin.getCurrentBankSortAssistItem();
		if (current == null || widgetItem.getWidget().getId() != InterfaceID.Bankmain.ITEMS)
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (itemId == current.id)
		{
			graphics.setColor(AMBER_FILL);
			graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 5, 5);
			graphics.setColor(AMBER_BORDER);
		}
		else if (itemId == current.anchorItemId)
		{
			graphics.setColor(GREEN_FILL);
			graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 5, 5);
			graphics.setColor(GREEN_BORDER);
		}
		else
		{
			return;
		}
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, 5, 5);
	}
}

package com.gildedspade.sync;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import okhttp3.internal.ws.RealWebSocket;
import okhttp3.internal.ws.WebSocketProtocol;
import okio.BufferedSink;
import okio.BufferedSource;
import okio.Okio;

import java.io.Closeable;
import java.io.IOException;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.net.SocketException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Random;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.Supplier;

@Slf4j
public class SyncWebSocketServer
{
	private static final Set<String> ALLOWED_ORIGINS = Set.of(
		"https://gildedspade.com",
		"http://localhost:3000"
	);

	private final GildedSpadeSyncPlugin plugin;
	private final ClientThread clientThread;
	private final Gson gson;
	private final ExecutorService executor;
	private final int port;
	private final AtomicBoolean serverActive = new AtomicBoolean(false);
	private final AtomicBoolean startupFailed = new AtomicBoolean(false);
	private final Set<Connection> connections = ConcurrentHashMap.newKeySet();

	private ServerSocket serverSocket;

	public SyncWebSocketServer(int port, GildedSpadeSyncPlugin plugin, ClientThread clientThread, Gson gson,
							   ExecutorService executor)
	{
		this.plugin = plugin;
		this.clientThread = clientThread;
		this.gson = Objects.requireNonNull(gson);
		this.executor = Objects.requireNonNull(executor);
		this.port = port;
	}

	public int getPort()
	{
		return port;
	}

	public boolean isActive()
	{
		return serverActive.get();
	}

	public boolean hasStartupFailed()
	{
		return startupFailed.get();
	}

	public int getConnectionCount()
	{
		return connections.size();
	}

	public void start() throws IOException
	{
		ServerSocket socket = new ServerSocket();
		socket.setReuseAddress(true);
		socket.bind(new InetSocketAddress(InetAddress.getLoopbackAddress(), port));

		serverSocket = socket;
		startupFailed.set(false);
		serverActive.set(true);

		executor.execute(this::acceptLoop);

		log.info("WebSocket server started successfully");
	}

	public void stop()
	{
		serverActive.set(false);
		closeQuietly(serverSocket);
		for (Connection connection : new ArrayList<>(connections))
		{
			connection.close(1001, "Server stopping");
			connection.closeQuietly();
		}
		connections.clear();
	}

	private void acceptLoop()
	{
		while (serverActive.get())
		{
			try
			{
				Socket socket = serverSocket.accept();
				if (connections.size() >= 1)
				{
					rejectConnection(socket, 503, "Connection limit reached");
					continue;
				}

				Connection connection = new Connection(socket);
				handleConnection(connection);
			}
			catch (SocketException e)
			{
				if (serverActive.get())
				{
					log.error("WebSocket accept loop failed", e);
					startupFailed.set(true);
					serverActive.set(false);
				}
			}
			catch (Exception e)
			{
				log.error("WebSocket accept loop failed", e);
			}
		}
	}

	private void handleConnection(Connection connection)
	{
		try
		{
			connection.handshake();
			connection.loopReader();
		}
		catch (Exception e)
		{
			if (serverActive.get())
			{
				log.debug("WebSocket connection ended for {}", connection.getRemoteSocketAddress(), e);
			}
		}
		finally
		{
			connections.remove(connection);
			connection.closeQuietly();
		}
	}

	private void handleMessage(Connection conn, String message)
	{
		try
		{
			JsonObject request = gson.fromJson(message, JsonObject.class);
			String messageType = request.get("type").getAsString();
			int sequenceId = request.has("sequenceId") ? request.get("sequenceId").getAsInt() : 0;

			log.debug("Received message type: {}", messageType);

			switch (messageType)
			{
				case "GET_QUESTS":
					handleRequest(conn, sequenceId, "QUEST_DATA", "GET_QUESTS", () ->
					{
						Map<String, Object> data = new HashMap<>();
						data.put("quests", plugin.getAllQuests());
						data.put("questPoints", plugin.getQuestPoints());
						data.put("username", plugin.getUsername());
						return data;
					});
					break;
				case "GET_ALL_DATA":
					handleRequest(conn, sequenceId, "ALL_DATA", "GET_ALL_DATA", plugin::getAllPlayerData);
					break;
				case "GET_STATS":
					handleRequest(conn, sequenceId, "STATS_DATA", "GET_STATS", plugin::getStatsPayload);
					break;
				case "GET_INVENTORY":
					handleRequest(conn, sequenceId, "INVENTORY_DATA", "GET_INVENTORY", plugin::getInventoryItems);
					break;
				case "GET_EQUIPMENT":
					handleRequest(conn, sequenceId, "EQUIPMENT_DATA", "GET_EQUIPMENT", plugin::getEquippedItems);
					break;
				case "GET_BANK":
					handleRequest(conn, sequenceId, "BANK_DATA", "GET_BANK", plugin::getBankedItems);
					break;
				case "GET_BANK_LAYOUT":
					handleRequest(conn, sequenceId, "BANK_LAYOUT_DATA", "GET_BANK_LAYOUT", plugin::getBankLayout);
					break;
				case "SET_BANK_FILTER":
					handleSetBankFilter(conn, sequenceId, request);
					break;
				case "START_BANK_SORT_ASSIST":
					handleStartBankSortAssist(conn, sequenceId, request);
					break;
				case "STOP_BANK_SORT_ASSIST":
					handleSortAction(conn, sequenceId, "STOP_BANK_SORT_ASSIST", plugin::stopBankSortAssist);
					break;
				case "SKIP_BANK_SORT_ASSIST_ITEM":
					handleSortAction(conn, sequenceId, "SKIP_BANK_SORT_ASSIST_ITEM", plugin::skipBankSortAssistItem);
					break;
				case "CONFIRM_BANK_SORT_ASSIST_ITEM":
					handleSortAction(conn, sequenceId, "CONFIRM_BANK_SORT_ASSIST_ITEM", plugin::confirmBankSortAssistItem);
					break;
				case "GET_BANK_SORT_ASSIST_STATUS":
					handleRequest(conn, sequenceId, "BANK_SORT_ASSIST_STATUS",
						"GET_BANK_SORT_ASSIST_STATUS", plugin::getBankSortAssistStatus);
					break;
				case "GET_DIARIES_DETAILED":
					handleRequest(conn, sequenceId, "DIARIES_DATA_DETAILED",
						"GET_DIARIES_DETAILED", plugin::getAchievementDiariesDetailed);
					break;
				case "GET_COMBAT_ACHIEVEMENTS":
					handleRequest(conn, sequenceId, "COMBAT_ACHIEVEMENTS_DATA",
						"GET_COMBAT_ACHIEVEMENTS", plugin::getCombatAchievements);
					break;
				case "GET_COLLECTION_LOG":
					handleRequest(conn, sequenceId, "COLLECTION_LOG_DATA",
						"GET_COLLECTION_LOG", plugin::getCollectionLog);
					break;
				case "GET_ACCOUNT_INFO":
					handleRequest(conn, sequenceId, "ACCOUNT_INFO_DATA",
						"GET_ACCOUNT_INFO", plugin::getAccountInfo);
					break;
				case "GET_SLAYER_TASK":
					handleRequest(conn, sequenceId, "SLAYER_TASK_DATA",
						"GET_SLAYER_TASK", plugin::getSlayerTask);
					break;
				case "GET_BIRDHOUSE_STATUS":
					handleRequest(conn, sequenceId, "BIRDHOUSE_STATUS_DATA",
						"GET_BIRDHOUSE_STATUS", plugin::getBirdhouseStatus);
					break;
				case "GET_DAILY_TASKS":
					handleRequest(conn, sequenceId, "DAILY_TASKS_DATA",
						"GET_DAILY_TASKS", plugin::getDailyTasks);
					break;
				case "GET_WORLD_LOCATION":
					handleRequest(conn, sequenceId, "WORLD_LOCATION_DATA",
						"GET_WORLD_LOCATION", plugin::getWorldLocation);
					break;
				case "PING":
					handlePing(conn, sequenceId);
					break;
				default:
					sendError(conn, sequenceId, "Unknown message type: " + messageType);
			}
		}
		catch (Exception e)
		{
			log.error("Error processing message", e);
			sendError(conn, 0, "Error processing message: " + e.getMessage());
		}
	}

	private <T> void handleRequest(Connection conn, int sequenceId, String responseType,
									String logName, Supplier<T> dataSupplier)
	{
		clientThread.invoke(() ->
		{
			try
			{
				Map<String, Object> response = new HashMap<>();
				response.put("type", responseType);
				response.put("sequenceId", sequenceId);
				response.put("data", dataSupplier.get());
				conn.send(gson.toJson(response));
				log.debug("Sent {} to {}", logName, conn.getRemoteSocketAddress());
			}
			catch (Exception e)
			{
				log.error("Error handling {}", logName, e);
				sendError(conn, sequenceId, "Error retrieving " + logName + ": " + e.getMessage());
			}
		});
	}

	private void handleSortAction(Connection conn, int sequenceId, String logName, Consumer<Runnable> action)
	{
		try
		{
			action.accept(() ->
			{
				sendBankSortAssistStatus(conn, sequenceId);
				log.debug("Handled {}", logName);
			});
		}
		catch (Exception e)
		{
			log.error("Error handling {}", logName, e);
			sendError(conn, sequenceId, "Error: " + e.getMessage());
		}
	}

	private void handleSetBankFilter(Connection conn, int sequenceId, JsonObject request)
	{
		try
		{
			List<Integer> itemIds = new ArrayList<>();
			if (request.has("itemIds") && request.get("itemIds").isJsonArray())
			{
				for (var element : request.getAsJsonArray("itemIds"))
				{
					itemIds.add(element.getAsInt());
				}
			}

			plugin.setBankFilter(itemIds);

			Map<String, Object> response = new HashMap<>();
			response.put("type", "BANK_FILTER_SET");
			response.put("sequenceId", sequenceId);
			response.put("itemCount", itemIds.size());
			conn.send(gson.toJson(response));

			log.info("Set bank filter to {} item IDs", itemIds.size());
		}
		catch (Exception e)
		{
			log.error("Error handling SET_BANK_FILTER", e);
			sendError(conn, sequenceId, "Error setting bank filter: " + e.getMessage());
		}
	}

	private void handleStartBankSortAssist(Connection conn, int sequenceId, JsonObject request)
	{
		try
		{
			List<Map<String, Object>> items = new ArrayList<>();
			if (request.has("items") && request.get("items").isJsonArray())
			{
				for (var element : request.getAsJsonArray("items"))
				{
					if (element.isJsonObject())
					{
						@SuppressWarnings("unchecked")
						Map<String, Object> item = gson.fromJson(element, Map.class);
						items.add(item);
					}
				}
			}

			int itemCount = items.size();
			plugin.startBankSortAssist(items, () ->
			{
				sendBankSortAssistStatus(conn, sequenceId);
				log.info("Started bank sort assist with {} items", itemCount);
			});
		}
		catch (Exception e)
		{
			log.error("Error handling START_BANK_SORT_ASSIST", e);
			sendError(conn, sequenceId, "Error starting bank sort assist: " + e.getMessage());
		}
	}

	private void sendBankSortAssistStatus(Connection conn, int sequenceId)
	{
		Map<String, Object> response = new HashMap<>();
		response.put("type", "BANK_SORT_ASSIST_STATUS");
		response.put("sequenceId", sequenceId);
		response.put("data", plugin.getBankSortAssistStatus());
		conn.send(gson.toJson(response));
	}

	private void handlePing(Connection conn, int sequenceId)
	{
		Map<String, Object> response = new HashMap<>();
		response.put("type", "PONG");
		response.put("sequenceId", sequenceId);
		conn.send(gson.toJson(response));
	}

	private void sendError(Connection conn, int sequenceId, String errorMessage)
	{
		Map<String, Object> response = new HashMap<>();
		response.put("type", "ERROR");
		response.put("sequenceId", sequenceId);
		response.put("error", errorMessage);
		conn.send(gson.toJson(response));
	}

	public void broadcastUsername()
	{
		clientThread.invokeLater(() ->
		{
			try
			{
				String username = plugin.getUsername();
				if (username.isEmpty())
				{
					return;
				}

				Map<String, Object> broadcast = new HashMap<>();
				broadcast.put("type", "USERNAME_CHANGED");
				broadcast.put("data", Map.of("username", username));
				broadcast(gson.toJson(broadcast));
				log.debug("Broadcast username: {}", username);
			}
			catch (Exception e)
			{
				log.error("Error broadcasting username", e);
			}
		});
	}

	public void broadcastBankSortAssistStatus(Map<String, Object> status)
	{
		try
		{
			Map<String, Object> broadcast = new HashMap<>();
			broadcast.put("type", "BANK_SORT_ASSIST_STATUS");
			broadcast.put("sequenceId", 0);
			broadcast.put("data", status);
			broadcast(gson.toJson(broadcast));
		}
		catch (Exception e)
		{
			log.error("Error broadcasting bank sort assist status", e);
		}
	}

	public void broadcastQuestUpdate()
	{
		clientThread.invokeLater(() ->
		{
			try
			{
				Map<String, Object> broadcast = new HashMap<>();
				broadcast.put("type", "PLAYER_UPDATE");
				broadcast.put("data", plugin.getAllPlayerData());
				broadcast(gson.toJson(broadcast));
				log.debug("Broadcast player data update");
			}
			catch (Exception e)
			{
				log.error("Error broadcasting player update", e);
			}
		});
	}

	private void broadcast(String message)
	{
		for (Connection connection : connections)
		{
			connection.send(message);
		}
	}

	private void rejectConnection(Socket socket, int statusCode, String message)
	{
		try (Socket ignored = socket;
			BufferedSink sink = Okio.buffer(Okio.sink(socket)))
		{
			sink.writeUtf8("HTTP/1.1 " + statusCode + " " + message + "\r\n");
			sink.writeUtf8("Connection: close\r\n");
			sink.writeUtf8("Content-Length: 0\r\n\r\n");
			sink.flush();
		}
		catch (IOException e)
		{
			log.debug("Unable to reject extra WebSocket connection", e);
		}
	}

	private static String headerValue(Map<String, String> headers, String name)
	{
		return headers.get(name.toLowerCase(Locale.ROOT));
	}

	private static boolean headerContains(Map<String, String> headers, String name, String expectedValue)
	{
		String value = headerValue(headers, name);
		return value != null && value.toLowerCase(Locale.ROOT).contains(expectedValue.toLowerCase(Locale.ROOT));
	}

	private static void closeQuietly(Closeable closeable)
	{
		if (closeable == null)
		{
			return;
		}
		try
		{
			closeable.close();
		}
		catch (IOException ignored)
		{
			// Best-effort shutdown.
		}
	}

	private class Connection extends WebSocketListener
	{
		private final Socket socket;
		private RealWebSocket webSocket;
		private BufferedSource source;
		private BufferedSink sink;

		Connection(Socket socket)
		{
			this.socket = socket;
		}

		void handshake() throws IOException
		{
			socket.setSoTimeout(5000);
			source = Okio.buffer(Okio.source(socket));
			sink = Okio.buffer(Okio.sink(socket));

			String requestLine = source.readUtf8LineStrict();
			String[] requestParts = requestLine.split(" ", 3);
			if (requestParts.length < 2 || !"GET".equals(requestParts[0]))
			{
				throw new IOException("Invalid WebSocket handshake request");
			}

			Map<String, String> headers = new HashMap<>();
			String line;
			while ((line = source.readUtf8LineStrict()).length() > 0)
			{
				int separator = line.indexOf(':');
				if (separator > 0)
				{
					headers.put(line.substring(0, separator).trim().toLowerCase(Locale.ROOT),
						line.substring(separator + 1).trim());
				}
			}

			String key = headerValue(headers, "Sec-WebSocket-Key");
			String origin = headerValue(headers, "Origin");
			if (!headerContains(headers, "Upgrade", "websocket")
				|| !headerContains(headers, "Connection", "Upgrade")
				|| key == null
				|| !"13".equals(headerValue(headers, "Sec-WebSocket-Version"))
				|| origin == null
				|| !ALLOWED_ORIGINS.contains(origin))
			{
				throw new IOException("Invalid WebSocket upgrade headers");
			}

			sink.writeUtf8("HTTP/1.1 101 Switching Protocols\r\n");
			sink.writeUtf8("Upgrade: websocket\r\n");
			sink.writeUtf8("Connection: Upgrade\r\n");
			sink.writeUtf8("Sec-WebSocket-Accept: " + WebSocketProtocol.acceptHeader(key) + "\r\n\r\n");
			sink.flush();

			String path = requestParts[1].startsWith("/") ? requestParts[1] : "/";
			Request request = new Request.Builder()
				.url("ws://localhost:" + port + path)
				.build();

			webSocket = new RealWebSocket(request, this, new Random(), 0);
			RealWebSocket.Streams streams = new RealWebSocket.Streams(false, source, sink)
			{
				@Override
				public void close() throws IOException
				{
					socket.close();
				}
			};
			webSocket.initReaderAndWriter("Gilded Spade Sync", streams);
			socket.setSoTimeout(0);
			connections.add(this);
			onOpen(webSocket, response(request));
		}

		void loopReader() throws IOException
		{
			webSocket.loopReader();
		}

		void send(String message)
		{
			WebSocket currentWebSocket = webSocket;
			if (currentWebSocket != null)
			{
				currentWebSocket.send(message);
			}
		}

		void close(int code, String reason)
		{
			WebSocket currentWebSocket = webSocket;
			if (currentWebSocket != null)
			{
				currentWebSocket.close(code, reason);
			}
		}

		void closeQuietly()
		{
			SyncWebSocketServer.closeQuietly(socket);
		}

		String getRemoteSocketAddress()
		{
			return String.valueOf(socket.getRemoteSocketAddress());
		}

		@Override
		public void onOpen(WebSocket webSocket, Response response)
		{
			log.info("New connection from: {}", getRemoteSocketAddress());
			try
			{
				broadcastUsername();
			}
			catch (Exception e)
			{
				log.error("Error broadcasting username on connection open", e);
			}
		}

		@Override
		public void onMessage(WebSocket webSocket, String text)
		{
			handleMessage(this, text);
		}

		@Override
		public void onClosing(WebSocket webSocket, int code, String reason)
		{
			webSocket.close(code, reason);
		}

		@Override
		public void onClosed(WebSocket webSocket, int code, String reason)
		{
			log.info("Connection closed: {} - Reason: {}", getRemoteSocketAddress(), reason);
		}

		@Override
		public void onFailure(WebSocket webSocket, Throwable t, Response response)
		{
			if (serverActive.get())
			{
				log.error("WebSocket error for connection: {}", getRemoteSocketAddress(), t);
			}
		}

		private Response response(Request request)
		{
			return new Response.Builder()
				.request(request)
				.protocol(Protocol.HTTP_1_1)
				.code(101)
				.message("Switching Protocols")
				.build();
		}
	}
}

package com.gildedspade.sync;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarPlayerID;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@Slf4j
class PlayerDataService
{
	private static final int QUEST_POINTS_VARP = 101;
	private static final int COMBAT_LEVEL_VARBIT = 13027;
	private static final int COLLECTION_LOG_COUNT_VARP = 2943;
	private static final int SPECIAL_ATTACK_PERCENT_VARP = 300;

	private final Client client;

	@Inject
	PlayerDataService(Client client)
	{
		this.client = client;
	}

	boolean isReady()
	{
		return client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null;
	}

	String getUsername()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return "";
		}
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || localPlayer.getName() == null)
		{
			return "";
		}
		return localPlayer.getName();
	}

	List<Map<String, Object>> getAllQuests()
	{
		List<Map<String, Object>> allQuests = new ArrayList<>();

		if (!isReady())
		{
			return allQuests;
		}

		for (Quest quest : Quest.values())
		{
			try
			{
				QuestState state = quest.getState(client);
				Map<String, Object> questData = new HashMap<>();
				questData.put("id", quest.getId());
				questData.put("name", quest.getName());
				questData.put("state", state.name());
				allQuests.add(questData);
			}
			catch (Exception e)
			{
				log.debug("Error checking quest {}: {}", quest.getName(), e.getMessage());
			}
		}

		return allQuests;
	}

	int getQuestPoints()
	{
		if (!isReady())
		{
			return 0;
		}
		return client.getVarpValue(QUEST_POINTS_VARP);
	}

	int getCombatLevel()
	{
		if (!isReady())
		{
			return 0;
		}
		return client.getVarbitValue(COMBAT_LEVEL_VARBIT);
	}

	Map<String, Map<String, Object>> getStats()
	{
		Map<String, Map<String, Object>> stats = new HashMap<>();

		if (!isReady())
		{
			return stats;
		}

		for (Skill skill : Skill.values())
		{
			try
			{
				Map<String, Object> skillData = new HashMap<>();
				skillData.put("level", client.getRealSkillLevel(skill));
				skillData.put("xp", client.getSkillExperience(skill));
				skillData.put("boostedLevel", client.getBoostedSkillLevel(skill));

				stats.put(skill.getName().toLowerCase().replace(" ", "_"), skillData);
			}
			catch (Exception e)
			{
				log.debug("Error getting stat for {}: {}", skill.getName(), e.getMessage());
			}
		}

		return stats;
	}

	Map<String, Object> getStatsPayload()
	{
		Map<String, Object> payload = new HashMap<>();
		payload.put("skills", getStats());
		payload.put("status", getPlayerStatus());
		return payload;
	}

	Map<String, Object> getPlayerStatus()
	{
		Map<String, Object> status = new HashMap<>();

		if (!isReady())
		{
			return status;
		}

		Map<String, Object> hitpoints = new HashMap<>();
		hitpoints.put("current", client.getBoostedSkillLevel(Skill.HITPOINTS));
		hitpoints.put("base", client.getRealSkillLevel(Skill.HITPOINTS));
		status.put("hitpoints", hitpoints);

		Map<String, Object> prayer = new HashMap<>();
		prayer.put("current", client.getBoostedSkillLevel(Skill.PRAYER));
		prayer.put("base", client.getRealSkillLevel(Skill.PRAYER));
		status.put("prayer", prayer);

		status.put("runEnergy", normalizePercentage(client.getEnergy()));
		status.put("specialAttack", normalizePercentage(client.getVarpValue(SPECIAL_ATTACK_PERCENT_VARP)));

		return status;
	}

	Map<String, Integer> getCollectionLog()
	{
		Map<String, Integer> collectionLog = new HashMap<>();

		if (!isReady())
		{
			return collectionLog;
		}

		collectionLog.put("unique_obtained", client.getVarpValue(COLLECTION_LOG_COUNT_VARP));

		return collectionLog;
	}

	Map<String, Object> getAccountInfo()
	{
		Map<String, Object> info = new HashMap<>();

		if (!isReady())
		{
			return info;
		}

		try
		{
			net.runelite.api.vars.AccountType accountType = client.getAccountType();
			info.put("type", accountType.name().toLowerCase());

			if (accountType.isGroupIronman())
			{
				int groupSize = client.getVarbitValue(net.runelite.api.gameval.VarbitID.GIM_GROUPSIZE);
				if (groupSize > 0)
				{
					info.put("groupSize", groupSize);
				}

				net.runelite.api.clan.ClanSettings groupSettings = client.getClanSettings(net.runelite.api.clan.ClanID.GROUP_IRONMAN);
				if (groupSettings != null)
				{
					info.put("groupName", groupSettings.getName());

					List<String> memberNames = new ArrayList<>();
					for (net.runelite.api.clan.ClanMember member : groupSettings.getMembers())
					{
						memberNames.add(member.getName());
					}
					info.put("members", memberNames);
				}
			}
		}
		catch (Exception e)
		{
			log.error("Error getting account info", e);
		}

		return info;
	}

	Map<String, Integer> getWorldLocation()
	{
		Map<String, Integer> location = new HashMap<>();

		if (!isReady())
		{
			return location;
		}

		WorldPoint point = client.getLocalPlayer().getWorldLocation();
		location.put("x", point.getX());
		location.put("y", point.getY());
		location.put("plane", point.getPlane());
		location.put("regionId", point.getRegionID());

		return location;
	}

	private int normalizePercentage(int value)
	{
		return value > 100 ? value / 10 : value;
	}
}

package com.gildedspade.sync;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws attention to the bank insert/swap control when a sort step requires it. */
class BankSortAssistModeOverlay extends Overlay
{
	private static final Color AMBER_FILL = new Color(255, 179, 0, 70);
	private static final Color AMBER_BORDER = new Color(255, 179, 0, 255);
	private final Client client;
	private final GildedSpadeSyncPlugin plugin;

	@Inject
	BankSortAssistModeOverlay(Client client, GildedSpadeSyncPlugin plugin)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isAwaitingBankSortAssistMoveMode())
		{
			return null;
		}

		Widget modeToggle = client.getWidget(InterfaceID.Bankmain.SWAP_INSERT);
		if (modeToggle == null || modeToggle.isHidden())
		{
			return null;
		}

		Rectangle bounds = modeToggle.getBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}

		graphics.setColor(AMBER_FILL);
		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 5, 5);
		graphics.setColor(AMBER_BORDER);
		graphics.setStroke(new BasicStroke(2f));
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width - 1, bounds.height - 1, 5, 5);
		return null;
	}
}

package com.gildedspade.sync;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

class BankCacheService
{
	private final Client client;
	private final Map<Integer, ItemData> cachedBankItems = new LinkedHashMap<>();
	private String cachedBankUsername = "";

	@Inject
	BankCacheService(Client client)
	{
		this.client = client;
	}

	void cacheBankItems(ItemContainer bankContainer)
	{
		String username = getUsername();
		if (username.isEmpty())
		{
			return;
		}

		cachedBankItems.clear();
		cachedBankUsername = username;
		Item[] items = bankContainer.getItems();

		for (int i = 0; i < items.length; i++)
		{
			Item item = items[i];
			if (item == null || item.getId() == -1 || item.getQuantity() <= 0)
			{
				continue;
			}

			ItemComposition itemComp = client.getItemDefinition(item.getId());
			if (itemComp == null || itemComp.getPlaceholderTemplateId() != -1)
			{
				continue;
			}

			cachedBankItems.put(i, new ItemData(item.getId(), itemComp.getName(), item.getQuantity(), i));
		}
	}

	void clearBankCacheIfDifferentPlayer()
	{
		String username = getUsername();
		if (!username.isEmpty() && !cachedBankUsername.isEmpty() && !username.equals(cachedBankUsername))
		{
			clearBankCache();
		}
	}

	int getCachedItemCount()
	{
		return cachedBankItems.size();
	}

	List<Map<String, Object>> getBankedItems()
	{
		List<Map<String, Object>> items = new ArrayList<>();
		if (!bankCacheBelongsToCurrentPlayer())
		{
			clearBankCache();
			return items;
		}

		for (ItemData itemData : cachedBankItems.values())
		{
			Map<String, Object> item = new LinkedHashMap<>();
			item.put("id", itemData.id);
			item.put("name", itemData.name);
			item.put("quantity", itemData.quantity);
			item.put("slot", itemData.slot);
			item.put("tabIndex", 0);
			items.add(item);
		}

		return items;
	}

	private void clearBankCache()
	{
		cachedBankItems.clear();
		cachedBankUsername = "";
	}

	private boolean bankCacheBelongsToCurrentPlayer()
	{
		if (cachedBankItems.isEmpty())
		{
			return true;
		}

		String username = getUsername();
		return !username.isEmpty() && username.equals(cachedBankUsername);
	}

	private String getUsername()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return "";
		}
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || localPlayer.getName() == null)
		{
			return "";
		}
		return localPlayer.getName();
	}

	private static class ItemData
	{
		final int id;
		final String name;
		final int quantity;
		final int slot;

		ItemData(int id, String name, int quantity, int slot)
		{
			this.id = id;
			this.name = name;
			this.quantity = quantity;
			this.slot = slot;
		}
	}
}

package com.gildedspade.sync;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.VarPlayerID;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Slf4j
class CombatAchievementService
{
	private static final int[] TIER_ENUM_IDS = {3981, 3982, 3983, 3984, 3985, 3986};
	private static final String[] TIER_NAMES = {
		"easy", "medium", "hard", "elite", "master", "grandmaster"
	};
	private static final int[] COMPLETION_VARPS = {
		VarPlayerID.CA_TASK_COMPLETED_0, VarPlayerID.CA_TASK_COMPLETED_1,
		VarPlayerID.CA_TASK_COMPLETED_2, VarPlayerID.CA_TASK_COMPLETED_3,
		VarPlayerID.CA_TASK_COMPLETED_4, VarPlayerID.CA_TASK_COMPLETED_5,
		VarPlayerID.CA_TASK_COMPLETED_6, VarPlayerID.CA_TASK_COMPLETED_7,
		VarPlayerID.CA_TASK_COMPLETED_8, VarPlayerID.CA_TASK_COMPLETED_9,
		VarPlayerID.CA_TASK_COMPLETED_10, VarPlayerID.CA_TASK_COMPLETED_11,
		VarPlayerID.CA_TASK_COMPLETED_12, VarPlayerID.CA_TASK_COMPLETED_13,
		VarPlayerID.CA_TASK_COMPLETED_14, VarPlayerID.CA_TASK_COMPLETED_15,
		VarPlayerID.CA_TASK_COMPLETED_16, VarPlayerID.CA_TASK_COMPLETED_17,
		VarPlayerID.CA_TASK_COMPLETED_18, VarPlayerID.CA_TASK_COMPLETED_19
	};

	private final Client client;
	private Map<String, List<TaskDefinition>> taskDefinitionsByTier;

	@Inject
	CombatAchievementService(Client client)
	{
		this.client = client;
	}

	Map<String, Object> getCombatAchievements()
	{
		Map<String, Object> combatAchievements = new HashMap<>();

		try
		{
			Map<String, List<TaskDefinition>> definitionsByTier = getTaskDefinitionsByTier();
			if (definitionsByTier == null)
			{
				return combatAchievements;
			}

			for (String tierName : TIER_NAMES)
			{
				Map<String, Object> tierData = new HashMap<>();
				List<Map<String, Object>> tasks = new ArrayList<>();
				int completedCount = 0;
				List<TaskDefinition> definitions = definitionsByTier.getOrDefault(tierName, Collections.emptyList());

				for (TaskDefinition definition : definitions)
				{
					boolean isCompleted = isTaskCompleted(definition);
					if (isCompleted)
					{
						completedCount++;
					}

					tasks.add(definition.toMap(isCompleted));
				}

				tierData.put("tasks", tasks);
				tierData.put("tasksComplete", completedCount);
				tierData.put("tasksTotal", definitions.size());

				combatAchievements.put(tierName, tierData);
			}

			int totalPoints = 0;
			for (int i = 0; i < TIER_NAMES.length; i++)
			{
				@SuppressWarnings("unchecked")
				Map<String, Object> tierData = (Map<String, Object>) combatAchievements.get(TIER_NAMES[i]);
				if (tierData != null)
				{
					int completed = (int) tierData.getOrDefault("tasksComplete", 0);
					totalPoints += completed * (i + 1);
				}
			}

			combatAchievements.put("totalPoints", totalPoints);
		}
		catch (Exception e)
		{
			log.error("Error getting combat achievements", e);
		}

		return combatAchievements;
	}

	private Map<String, List<TaskDefinition>> getTaskDefinitionsByTier()
	{
		if (taskDefinitionsByTier != null)
		{
			return taskDefinitionsByTier;
		}

		Map<String, List<TaskDefinition>> definitionsByTier = new LinkedHashMap<>();
		for (int tierIndex = 0; tierIndex < TIER_ENUM_IDS.length; tierIndex++)
		{
			int enumId = TIER_ENUM_IDS[tierIndex];
			String tierName = TIER_NAMES[tierIndex];
			EnumComposition tierEnum = client.getEnum(enumId);
			if (tierEnum == null)
			{
				log.warn("Enum {} for tier {} returned null", enumId, tierName);
				return null;
			}

			int[] structIds = tierEnum.getIntVals();
			List<TaskDefinition> definitions = new ArrayList<>(structIds.length);
			for (int structId : structIds)
			{
				try
				{
					StructComposition struct = client.getStructComposition(structId);
					int taskId = struct.getIntValue(1306);
					String taskName = struct.getStringValue(1308);
					int varpIndex = taskId / 32;
					int bitPosition = taskId % 32;

					if (varpIndex >= COMPLETION_VARPS.length)
					{
						log.warn("Task ID {} has varp index {} which exceeds array length {}",
							taskId, varpIndex, COMPLETION_VARPS.length);
					}

					definitions.add(new TaskDefinition(taskId, taskName, varpIndex, bitPosition));
				}
				catch (Exception e)
				{
					log.debug("Error caching combat achievement task {}: {}", structId, e.getMessage());
				}
			}

			definitionsByTier.put(tierName, Collections.unmodifiableList(definitions));
			log.debug("Cached {} combat achievement definitions for {} tier", definitions.size(), tierName);
		}

		taskDefinitionsByTier = Collections.unmodifiableMap(definitionsByTier);
		return taskDefinitionsByTier;
	}

	private boolean isTaskCompleted(TaskDefinition definition)
	{
		if (definition.varpIndex >= COMPLETION_VARPS.length)
		{
			return false;
		}

		int varpValue = client.getVarpValue(COMPLETION_VARPS[definition.varpIndex]);
		return (varpValue & (1 << definition.bitPosition)) != 0;
	}

	private static class TaskDefinition
	{
		final int taskId;
		final String taskName;
		final int varpIndex;
		final int bitPosition;

		TaskDefinition(int taskId, String taskName, int varpIndex, int bitPosition)
		{
			this.taskId = taskId;
			this.taskName = taskName;
			this.varpIndex = varpIndex;
			this.bitPosition = bitPosition;
		}

		Map<String, Object> toMap(boolean completed)
		{
			Map<String, Object> task = new HashMap<>();
			task.put("taskId", taskId);
			task.put("taskName", taskName);
			task.put("completed", completed);
			return task;
		}
	}
}

package com.gildedspade.sync;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

@Slf4j
class BankSortAssistService
{
	private final Client client;
	private final ClientThread clientThread;
	private final Consumer<List<Integer>> bankFilterSetter;
	private final Consumer<Map<String, Object>> statusBroadcaster;

	private volatile BankSortAssistSession bankSortAssistSession;
	private boolean bankSortAssistModeRefreshQueued;
	private List<Integer> currentFilterIds = Collections.emptyList();

	@Inject
	BankSortAssistService(Client client, ClientThread clientThread,
		Consumer<List<Integer>> bankFilterSetter, Consumer<Map<String, Object>> statusBroadcaster)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.bankFilterSetter = bankFilterSetter;
		this.statusBroadcaster = statusBroadcaster;
	}

	void startBankSortAssist(List<Map<String, Object>> items)
	{
		startBankSortAssist(items, null);
	}

	void startBankSortAssist(List<Map<String, Object>> items, Runnable afterAction)
	{
		clientThread.invoke(() ->
		{
			try
			{
				List<BankSortAssistItem> assistItems = new ArrayList<>();
				for (Map<String, Object> item : items)
				{
					int id = getIntValue(item.get("id"), -1);
					if (id <= 0)
					{
						continue;
					}

					String name = getStringValue(item.get("name"), "Item " + id);
					String targetTabId = getStringValue(item.get("targetTabId"), "main");
					String targetTabName = getStringValue(item.get("targetTabName"), "Main");
					int targetPosition = getIntValue(item.get("targetPosition"), assistItems.size());
					String requiredMoveMode = getMoveModeValue(item.get("requiredMoveMode"));
					String actionType = getSortActionType(item.get("actionType"));
					int anchorItemId = getIntValue(item.get("anchorItemId"), -1);
					String anchorItemName = getStringValue(item.get("anchorItemName"), "");

					assistItems.add(new BankSortAssistItem(id, name, targetTabId, targetTabName, targetPosition,
						requiredMoveMode, actionType, anchorItemId, anchorItemName));
				}

				bankSortAssistSession = new BankSortAssistSession(assistItems);
				applyCurrentBankSortAssistStep();
				broadcastBankSortAssistStatus();
			}
			finally
			{
				runAfterAction(afterAction);
			}
		});
	}

	void stopBankSortAssist()
	{
		stopBankSortAssist(null);
	}

	void stopBankSortAssist(Runnable afterAction)
	{
		clientThread.invoke(() ->
		{
			try
			{
				if (bankSortAssistSession != null)
				{
					bankSortAssistSession.active = false;
				}
				currentFilterIds = Collections.emptyList();
				bankFilterSetter.accept(currentFilterIds);
				broadcastBankSortAssistStatus();
			}
			finally
			{
				runAfterAction(afterAction);
			}
		});
	}

	void skipBankSortAssistItem()
	{
		skipBankSortAssistItem(null);
	}

	void skipBankSortAssistItem(Runnable afterAction)
	{
		clientThread.invoke(() ->
		{
			try
			{
				if (bankSortAssistSession == null || !bankSortAssistSession.active)
				{
					broadcastBankSortAssistStatus();
					return;
				}

				bankSortAssistSession.skipCurrent();
				applyCurrentBankSortAssistStep();
				broadcastBankSortAssistStatus();
			}
			finally
			{
				runAfterAction(afterAction);
			}
		});
	}

	void confirmBankSortAssistItem()
	{
		confirmBankSortAssistItem(null);
	}

	void confirmBankSortAssistItem(Runnable afterAction)
	{
		clientThread.invoke(() ->
		{
			try
			{
				completeCurrentBankSortAssistStep();
				broadcastBankSortAssistStatus();
			}
			finally
			{
				runAfterAction(afterAction);
			}
		});
	}

	private void runAfterAction(Runnable afterAction)
	{
		if (afterAction == null)
		{
			return;
		}
		try
		{
			afterAction.run();
		}
		catch (Exception e)
		{
			log.error("Error running bank sort assist completion callback", e);
		}
	}

	Map<String, Object> getBankSortAssistStatus()
	{
		Map<String, Object> status = new HashMap<>();
		BankSortAssistSession session = bankSortAssistSession;
		if (session == null)
		{
			status.put("active", false);
			status.put("total", 0);
			status.put("completed", 0);
			status.put("skipped", 0);
			status.put("remaining", 0);
			return status;
		}

		status.put("active", session.active);
		status.put("total", session.items.size());
		status.put("completed", session.completedCount);
		status.put("skipped", session.skippedCount);
		status.put("remaining", Math.max(0, session.items.size() - session.currentIndex));
		status.put("currentIndex", session.currentIndex);

		BankSortAssistItem current = session.getCurrent();
		if (current != null && session.active)
		{
			status.put("currentStep", current.toMap());
			status.put("currentMoveMode", getCurrentBankSortAssistMoveMode());
			status.put("awaitingMoveMode", !isBankSortAssistMoveModeSatisfied(current));
		}

		return status;
	}

	void advanceBankSortAssistAfterBankChange()
	{
		if (bankSortAssistSession == null || !bankSortAssistSession.active)
		{
			return;
		}

		if (!bankSortAssistSession.awaitingBankChange)
		{
			applyCurrentBankSortAssistStep();
			broadcastBankSortAssistStatus();
			return;
		}

		completeCurrentBankSortAssistStep();
		broadcastBankSortAssistStatus();
	}

	void handleVarbitChanged(int varbitId, int varpId)
	{
		if (varbitId != VarbitID.BANK_INSERTMODE && varpId != net.runelite.api.gameval.VarPlayerID.BANKINSERT)
		{
			return;
		}

		BankSortAssistItem current = getCurrentBankSortAssistItem();
		if (current == null || current.requiredMoveMode == null || bankSortAssistSession == null || bankSortAssistModeRefreshQueued)
		{
			return;
		}

		bankSortAssistModeRefreshQueued = true;
		clientThread.invokeLater(() ->
		{
			bankSortAssistModeRefreshQueued = false;
			BankSortAssistItem refreshedCurrent = getCurrentBankSortAssistItem();
			if (refreshedCurrent == null || refreshedCurrent.requiredMoveMode == null || bankSortAssistSession == null)
			{
				return;
			}

			boolean modeSatisfied = isBankSortAssistMoveModeSatisfied(refreshedCurrent);
			if (!modeSatisfied || !bankSortAssistSession.awaitingBankChange)
			{
				applyCurrentBankSortAssistStep();
				broadcastBankSortAssistStatus();
			}
		});
	}

	BankSortAssistItem getCurrentBankSortAssistItem()
	{
		return bankSortAssistSession == null ? null : bankSortAssistSession.getCurrent();
	}

	boolean isAwaitingBankSortAssistMoveMode()
	{
		BankSortAssistItem current = getCurrentBankSortAssistItem();
		return current != null && !isBankSortAssistMoveModeSatisfied(current);
	}

	private void completeCurrentBankSortAssistStep()
	{
		if (bankSortAssistSession == null || !bankSortAssistSession.active)
		{
			return;
		}
		if (!isBankSortAssistMoveModeSatisfied(bankSortAssistSession.getCurrent()))
		{
			applyCurrentBankSortAssistStep();
			return;
		}

		bankSortAssistSession.completeCurrent();
		applyCurrentBankSortAssistStep();
	}

	private void applyCurrentBankSortAssistStep()
	{
		if (bankSortAssistSession == null)
		{
			return;
		}

		BankSortAssistItem current = bankSortAssistSession.getCurrent();
		if (current == null)
		{
			bankSortAssistSession.active = false;
			bankSortAssistSession.awaitingBankChange = false;
			currentFilterIds = Collections.emptyList();
			bankFilterSetter.accept(currentFilterIds);
			return;
		}
		if (!isBankSortAssistMoveModeSatisfied(current))
		{
			bankSortAssistSession.awaitingBankChange = false;
			if (!currentFilterIds.isEmpty())
			{
				currentFilterIds = Collections.emptyList();
				bankFilterSetter.accept(currentFilterIds);
			}
			return;
		}

		Widget bankContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankContainer == null || bankContainer.isHidden())
		{
			bankSortAssistSession.awaitingBankChange = false;
			return;
		}

		bankSortAssistSession.awaitingBankChange = true;
		List<Integer> filterIds = new ArrayList<>();
		filterIds.add(current.id);
		if (current.anchorItemId > 0 && current.anchorItemId != current.id)
		{
			filterIds.add(current.anchorItemId);
		}
		currentFilterIds = filterIds;
		bankFilterSetter.accept(filterIds);
	}

	private void broadcastBankSortAssistStatus()
	{
		statusBroadcaster.accept(getBankSortAssistStatus());
	}

	private boolean isBankSortAssistMoveModeSatisfied(BankSortAssistItem item)
	{
		if (item == null || item.requiredMoveMode == null)
		{
			return true;
		}

		return item.requiredMoveMode.equals(getCurrentBankSortAssistMoveMode());
	}

	private String getCurrentBankSortAssistMoveMode()
	{
		return client.getVarbitValue(VarbitID.BANK_INSERTMODE) == 1 ? "insert" : "swap";
	}

	private int getIntValue(Object value, int fallback)
	{
		if (value instanceof Number)
		{
			return ((Number) value).intValue();
		}
		return fallback;
	}

	private String getStringValue(Object value, String fallback)
	{
		return value instanceof String && !((String) value).isBlank() ? (String) value : fallback;
	}

	private String getMoveModeValue(Object value)
	{
		if (!(value instanceof String))
		{
			return null;
		}

		String moveMode = ((String) value).trim().toLowerCase();
		return moveMode.equals("insert") || moveMode.equals("swap") ? moveMode : null;
	}

	private String getSortActionType(Object value)
	{
		if (!(value instanceof String))
		{
			return "move-tab";
		}

		String actionType = ((String) value).trim().toLowerCase();
		return actionType.equals("insert-before") || actionType.equals("insert-after") || actionType.equals("swap")
			? actionType
			: "move-tab";
	}

	private static class BankSortAssistSession
	{
		final List<BankSortAssistItem> items;
		volatile int currentIndex;
		volatile int completedCount;
		volatile int skippedCount;
		volatile boolean active;
		volatile boolean awaitingBankChange;

		BankSortAssistSession(List<BankSortAssistItem> items)
		{
			this.items = items;
			this.active = !items.isEmpty();
		}

		BankSortAssistItem getCurrent()
		{
			if (!active || currentIndex < 0 || currentIndex >= items.size())
			{
				return null;
			}
			return items.get(currentIndex);
		}

		private void advance()
		{
			if (getCurrent() == null)
			{
				active = false;
				awaitingBankChange = false;
				return;
			}
			currentIndex++;
			awaitingBankChange = false;
			if (currentIndex >= items.size())
			{
				active = false;
			}
		}

		void completeCurrent()
		{
			completedCount++;
			advance();
		}

		void skipCurrent()
		{
			skippedCount++;
			advance();
		}
	}

	static class BankSortAssistItem
	{
		final int id;
		final String name;
		final String targetTabId;
		final String targetTabName;
		final int targetPosition;
		final String requiredMoveMode;
		final String actionType;
		final int anchorItemId;
		final String anchorItemName;

		BankSortAssistItem(int id, String name, String targetTabId, String targetTabName, int targetPosition,
			String requiredMoveMode, String actionType, int anchorItemId, String anchorItemName)
		{
			this.id = id;
			this.name = name;
			this.targetTabId = targetTabId;
			this.targetTabName = targetTabName;
			this.targetPosition = targetPosition;
			this.requiredMoveMode = requiredMoveMode;
			this.actionType = actionType;
			this.anchorItemId = anchorItemId;
			this.anchorItemName = anchorItemName;
		}

		Map<String, Object> toMap()
		{
			Map<String, Object> map = new HashMap<>();
			map.put("id", id);
			map.put("name", name);
			map.put("targetTabId", targetTabId);
			map.put("targetTabName", targetTabName);
			map.put("targetPosition", targetPosition);
			map.put("actionType", actionType);
			if (requiredMoveMode != null)
			{
				map.put("requiredMoveMode", requiredMoveMode);
			}
			if (anchorItemId > 0)
			{
				map.put("anchorItemId", anchorItemId);
				map.put("anchorItemName", anchorItemName);
			}
			return map;
		}
	}
}
